def compute_aim_point(
    planner: TerrainPlanner,
    pred_x: float,
    pred_y: float,
    tx: float,
    ty: float,
    nx_p: float,
    ny_p: float,
    offset: float = 0.70,
) -> Tuple[float, float]:
    d1 = math.hypot(pred_x - tx, pred_y - ty)
    d2 = math.hypot(nx_p - tx, ny_p - ty)
    ux1, uy1 = ((pred_x - tx) / d1, (pred_y - ty) / d1) if d1 > 1e-3 else (0.0, 0.0)
    ux2, uy2 = ((nx_p - tx) / d2, (ny_p - ty) / d2) if d2 > 1e-3 else (ux1, uy1)
    bx, by = ux1 + ux2, uy1 + uy2
    bn = math.hypot(bx, by)
    if bn > 1e-3:
        ax = tx + offset * (bx / bn)
        ay = ty + offset * (by / bn)
    else:
        ax = tx + offset * ux1
        ay = ty + offset * uy1
    ci, cj, _, _ = planner.surf.locate(ax, ay)
    if planner.cell_safe[cj][ci] and planner.surf.slope(ax, ay) <= 0.28:
        return ax, ay
    return tx, ty


def play_one_mission(tools: Any, verbose: bool = True) -> Dict[str, Any]:
    t_start = time.time()
    rules = tools.rules()
    world = tools.map()
    mission_id = world.get("mission", 1)
    max_ticks = int(rules["max_ticks"])
    delay_ticks = int(rules["delay_ticks"])

    surf = Surface(world["cell_m"], world["elevation_cm"], world["terrain"])
    base_xy = (float(world["base"][0]), float(world["base"][1]))
    planner = TerrainPlanner(surf, base_xy, world["targets"])
    estimator = StateEstimator(surf, base_xy)

    targets_by_id: Dict[str, Dict[str, Any]] = {t["id"]: t for t in world["targets"]}
    sampled_or_pending: set[str] = set()
    pending_sample_ticks: Dict[int, Tuple[str, int]] = {}
    queued_cmds: Dict[int, Dict[str, Any]] = {}
    cmd_sent_tick: Dict[int, int] = {}
    last_reserved_tick = 0
    current_tick = 0

    # Process any initial packets in telemetry_log
    for pkt in tools.telemetry_log():
        current_tick = max(current_tick, int(pkt.get("received_tick", 0)))
        for s_id in pkt.get("sampled_targets", []):
            sampled_or_pending.add(s_id)

    unsampled = [t for tid, t in targets_by_id.items() if tid not in sampled_or_pending]
    planned_seq = plan_tour(
        planner,
        base_xy,
        delay_ticks,
        99.85,
        estimator.solar_eff,
        unsampled,
        lns_iters=220,
    )
    if verbose:
        print(
            f"[Mission {mission_id}] Initial plan ({len(planned_seq)} targets, {time.time()-t_start:.2f}s): {planned_seq}"
        )

    while True:
        next_exec_tick = max(current_tick + delay_ticks + 1, last_reserved_tick + 1)
        if next_exec_tick <= max_ticks:
            pred_x, pred_y, pred_bat = estimator.predict_state(queued_cmds, next_exec_tick - 1)
            planned_seq = [tid for tid in planned_seq if tid not in sampled_or_pending and tid in targets_by_id]

            u_cur = planner.nearest_safe_node(pred_x, pred_y)
            t_ret = int(math.ceil(planner.to_base_ticks[u_cur] * 1.05)) + 1
            rem_ticks = max_ticks - next_exec_tick + 1

            if planned_seq:
                tid = planned_seq[0]
                t_obj = targets_by_id[tid]
                tx, ty = float(t_obj["x"]), float(t_obj["y"])
                d_target = math.hypot(pred_x - tx, pred_y - ty)
                if d_target > 1.35 and rem_ticks <= t_ret + 5:
                    if verbose:
                        print(f"[Tick {current_tick}] Exec {next_exec_tick}: Return-to-base override (rem={rem_ticks}, t_ret={t_ret})")
                    planned_seq.clear()
                elif d_target <= 1.35 and rem_ticks <= t_ret + 3:
                    planned_seq.clear()

            if planned_seq:
                tid = planned_seq[0]
                t_obj = targets_by_id[tid]
                tx, ty = float(t_obj["x"]), float(t_obj["y"])
                d_target = math.hypot(pred_x - tx, pred_y - ty)
                sol_next = 2.8 * estimator.solar_eff * math.sin(math.pi * (min(420, next_exec_tick) + 56) / (420 + 112))

                if d_target <= 1.35:
                    if next_exec_tick < int(t_obj.get("appear_tick", 0)):
                        cmd = {"action": "wait"}
                    elif pred_bat + sol_next - 2.15 < 8.5:
                        cmd = {"action": "wait"}
                    else:
                        cmd = {"action": "sample"}
                        sampled_or_pending.add(tid)
                        pending_sample_ticks[next_exec_tick] = (tid, current_tick)
                        planned_seq.pop(0)
                else:
                    if pred_bat < 11.0:
                        cmd = {"action": "wait"}
                    else:
                        if len(planned_seq) >= 2:
                            nt_obj = targets_by_id[planned_seq[1]]
                            nx_p, ny_p = float(nt_obj["x"]), float(nt_obj["y"])
                        else:
                            nx_p, ny_p = base_xy
                        aim_x, aim_y = compute_aim_point(planner, pred_x, pred_y, tx, ty, nx_p, ny_p, offset=0.70)
                        wps = planner.find_waypoints(pred_x, pred_y, aim_x, aim_y)
                        wx, wy = wps[0]
                        t_center = (tx, ty) if len(wps) == 1 else None
                        cmd = compute_drive_command(
                            surf, pred_x, pred_y, wx, wy, t_center, estimator.est_bias, estimator.slip_est
                        )
            else:
                bx, by = base_xy
                d_base = math.hypot(pred_x - bx, pred_y - by)
                if d_base <= 1.55:
                    cmd = {"action": "wait"}
                elif pred_bat < 8.0 and rem_ticks > t_ret + 3:
                    cmd = {"action": "wait"}
                else:
                    wps = planner.find_waypoints(pred_x, pred_y, bx, by)
                    wx, wy = wps[0]
                    t_center = (bx, by) if len(wps) == 1 else None
                    cmd = compute_drive_command(
                        surf, pred_x, pred_y, wx, wy, t_center, estimator.est_bias, estimator.slip_est
                    )

            try:
                acks = tools.uplink([cmd])
                exec_t = int(acks[0]["execute_tick"]) if (acks and isinstance(acks[0], dict) and "execute_tick" in acks[0]) else next_exec_tick
                queued_cmds[exec_t] = cmd
                cmd_sent_tick[exec_t] = current_tick
                last_reserved_tick = max(last_reserved_tick, exec_t)
            except ValueError as e:
                if verbose:
                    print(f"[Tick {current_tick}] Uplink ValueError: {e}")

        out = tools.advance(1)
        current_tick = int(out.get("current_tick", current_tick + 1))
        ep_done = bool(out.get("episode_complete", False))
        camp_done = bool(out.get("campaign_complete", False))

        need_replan = False
        need_map_refresh = False

        for pkt in out.get("packets", []):
            if pkt.get("mission", mission_id) != mission_id:
                continue
            ptk = int(pkt["tick"])
            for ev in pkt.get("events", []):
                ev_type = ev.get("type", "") if isinstance(ev, dict) else str(ev)
                if "discover" in ev_type:
                    need_map_refresh = True
                if "stop" in ev_type or "tilt" in ev_type or "boundary" in ev_type:
                    need_replan = True

            _, safety_stop = estimator.step_telemetry(pkt, queued_cmds.get(ptk), targets_by_id)
            if safety_stop:
                if verbose:
                    print(f"[Tick {current_tick}] Safety stop detected at state_tick={ptk}!")
                # Clear commands that were already in queue at ptk
                for k_tk in list(queued_cmds.keys()):
                    if k_tk > ptk and cmd_sent_tick.get(k_tk, 999) <= ptk:
                        del queued_cmds[k_tk]
                need_replan = True

            if ptk in pending_sample_ticks:
                exp_tid, _ = pending_sample_ticks.pop(ptk)
                if exp_tid not in estimator.sampled_set:
                    if verbose:
                        print(f"[Tick {current_tick}] Sample miss on {exp_tid} at tick {ptk}, re-adding!")
                    sampled_or_pending.discard(exp_tid)
                    planned_seq.insert(0, exp_tid)
                    need_replan = True

        if ep_done:
            if verbose:
                print(f"[Mission {mission_id}] Episode complete at tick {current_tick} (campaign_complete={camp_done})")
            return out

        if need_map_refresh:
            w_new = tools.map()
            if w_new.get("mission", mission_id) == mission_id:
                for t in w_new.get("targets", []):
                    if t["id"] not in targets_by_id:
                        targets_by_id[t["id"]] = t
                        if verbose:
                            print(f"[Tick {current_tick}] Discovered target {t['id']} val={t['value']} dl={t['deadline_tick']} at ({t['x']},{t['y']})")
                        need_replan = True

        if current_tick in (12, 65, 130, 195, 260, 325):
            need_replan = True

        if need_replan and current_tick < 375:
            planner.rebuild_graph(estimator.slip_est)
            nx_exec = max(current_tick + delay_ticks + 1, last_reserved_tick + 1)
            px, py, pbat = estimator.predict_state(queued_cmds, nx_exec - 1)
            unsampled = [t for tid, t in targets_by_id.items() if tid not in sampled_or_pending]
            if unsampled:
                new_seq = plan_tour(
                    planner,
                    (px, py),
                    nx_exec - 1,
                    pbat,
                    estimator.solar_eff,
                    unsampled,
                    seed_seq_ids=planned_seq,
                    lns_iters=55,
                )
                if new_seq != planned_seq and verbose:
                    print(f"[Tick {current_tick}] Replanned ({len(new_seq)} remaining): {new_seq}")
                planned_seq = new_seq


if __name__ == "__main__":
